-- Expand the shared system exercise catalog so every user has the same exercises.
-- 1) upsert 68 additional system exercises (ids match the offline catalogs: ex-<slug>)
-- 2) add their muscle groups and alternatives
-- 3) earlier one-off imports created per-user copies of these exercises (slugs 'gymlife-*');
--    re-point their references (templates, sessions, stretching routines, alternative id
--    arrays) to the system rows and remove the copies.

VALUES ('ex-push-up', 'push-up', NULL, 'Push-Up', 'Bodyweight exercise for the chest, with core, shoulders assisting.', ARRAY['Lie on an exercise floor mat, face down.', 'Press your toes against the floor and place your hands flat on the ground shoulder width apart, fingers extended forward.', 'Descend by flexing at the elbow, lowering your chest toward the ground.', 'At the bottom contract your chest as you push off the ground and return to the starting position.']::TEXT[], 'BODYWEIGHT'::"ExerciseCategory", 'STRENGTH'::"ExerciseType", 'CHEST'::"MuscleGroup", 'BODYWEIGHT'::"EquipmentType", NULL, ARRAY['chest', 'liegestütz', 'push up', 'push-up']::TEXT[], true, NOW(), NOW())
