VALUES ('ex-dumbbell-bench-press', 'dumbbell-bench-press', NULL, 'Dumbbell Bench Press', 'Dumbbell exercise for the chest, with core, shoulders assisting.', ARRAY['Lie down on a flat bench with a dumbbell in each hand resting on top of your thighs.', 'Press dumbbells straight up into the air and lock arms out at a full extended position and with the dumbbells touching at the peak of the movement.', 'Return to the starting position.']::TEXT[], 'COMPOUND'::"ExerciseCategory", 'STRENGTH'::"ExerciseType", 'CHEST'::"MuscleGroup", 'DUMBBELL'::"EquipmentType", NULL, ARRAY['chest', 'dumbbell flat bench press', 'flachbank', 'kurzhantel bankdrücken']::TEXT[], true, NOW(), NOW())
