VALUES ('ex-dumbbell-fly', 'dumbbell-fly', NULL, 'Dumbbell Fly', 'Dumbbell exercise for the chest, with shoulders, triceps assisting.', ARRAY['Lie down on a flat bench with a dumbbell on each hand resting on top of your thighs.', 'The palms of your hand will be facing each other.', 'Lift the dumbbells one at at time.', 'Hold the dumbbells in front of you, shoulder width apart.', 'The palms of your hands should be facing each other.', 'Lift the dumbbells as if you were pressing them stop and hold the weight before you lock out.', 'Bend your elbows slightly and lower your arms at both sides using a wide arc.', 'Keep lowering your arms until you feel a stretch on your chest.']::TEXT[], 'ISOLATION'::"ExerciseCategory", 'STRENGTH'::"ExerciseType", 'CHEST'::"MuscleGroup", 'DUMBBELL'::"EquipmentType", NULL, ARRAY['chest', 'flat bench dumbbell fly', 'fliegende', 'kurzhantel fliegende']::TEXT[], true, NOW(), NOW())
