VALUES ('ex-incline-dumbbell-fly', 'incline-dumbbell-fly', NULL, 'Incline Dumbbell Fly', 'Dumbbell exercise for the chest, with shoulders assisting.', ARRAY['Hold a dumbbell on each hand and lie on an incline bench that is set to an incline angle of no more than 30 degrees.', 'Extend your arms above you with your elbows slightly bent.', 'Rotate your wrists so that the palms of your hands are facing you.', 'This is the starting position.', 'Start to slowly lower the arms to the side while keeping the arms extended and while rotating the wrists until the palms of the hand are facing each other.', 'Exhale and start to bring the dumbbells back to the starting position by reversing the motion.', 'Rotate your hands so that your pinky fingers are next to each other again.']::TEXT[], 'ISOLATION'::"ExerciseCategory", 'STRENGTH'::"ExerciseType", 'CHEST'::"MuscleGroup", 'DUMBBELL'::"EquipmentType", NULL, ARRAY['chest', 'incline bench dumbbell fly', 'schrägbank fliegende']::TEXT[], true, NOW(), NOW())
