VALUES ('ex-incline-barbell-bench-press', 'incline-barbell-bench-press', NULL, 'Incline Barbell Bench Press', 'Barbell exercise for the chest, with core, shoulders assisting.', ARRAY['Lie down on an incline bench.', 'Gripping the bar with a medium-width grip, lift the bar off the rack.', 'Hold it straight over your head, keeping your arms locked.', 'This is the starting position for the exercise.', 'Remove the bar from the rack, holding the weight above your chest with your arms extended.', 'Move the bar down toward your upper chest.', 'Pause for a moment and push the bar back to the starting position.', 'Arms should be locked.']::TEXT[], 'COMPOUND'::"ExerciseCategory", 'STRENGTH'::"ExerciseType", 'CHEST'::"MuscleGroup", 'BARBELL'::"EquipmentType", NULL, ARRAY['chest', 'incline barbell bench press', 'langhantel schrägbank', 'schrägbankdrücken']::TEXT[], true, NOW(), NOW())
