VALUES ('ex-machine-incline-chest-press', 'machine-incline-chest-press', NULL, 'Machine Incline Chest Press', 'Machine exercise for the chest, with triceps assisting.', ARRAY['Firmly grasp the handles.', 'Pull your shoulder blades together and lift your elbows to grip level.', 'Push your arms inclined forward and up till they are fully stretched.', 'Move the handles towards each other to let your arms meet, then lower them back to your chest at a slightly slower pace.', 'Repeat the exercise.']::TEXT[], 'MACHINE'::"ExerciseCategory", 'STRENGTH'::"ExerciseType", 'CHEST'::"MuscleGroup", 'MACHINE'::"EquipmentType", NULL, ARRAY['chest', 'inclined chest press', 'schrägbankdrücken maschine']::TEXT[], true, NOW(), NOW())
