VALUES ('ex-chin-up', 'chin-up', NULL, 'Chin-Up', 'Bodyweight exercise for the back, with biceps, forearms assisting.', ARRAY['Facing a pull up bar, grasp the handles with your palms facing away from you and arms at a distance smaller than your shoulder width.', 'Pull your torso up until the bar touches your upper chest by drawing the shoulders and the upper arms down and back.', 'Exhale during this movement.', 'Contract your back muscles and then inhale as you extend your arms completely and return back to the starting position.']::TEXT[], 'BODYWEIGHT'::"ExerciseCategory", 'STRENGTH'::"ExerciseType", 'BACK'::"MuscleGroup", 'BODYWEIGHT'::"EquipmentType", NULL, ARRAY['back', 'chinup', 'close grip pull-up', 'close grip pullup / chinup', 'klimmzug untergriff']::TEXT[], true, NOW(), NOW())
