VALUES ('ex-chest-supported-dumbbell-row', 'chest-supported-dumbbell-row', NULL, 'Chest-Supported Dumbbell Row', 'Dumbbell exercise for the back, with biceps, forearms assisting.', ARRAY['Using a neutral grip, lean into an incline bench.', 'Grab a dumbbell in each hand and rotate your hands so your palms are facing each other.', 'Retract the shoulder blades and flex the elbows to row the dumbbells to your side.', 'Hold for a moment and then lower the dumbbells back down.']::TEXT[], 'COMPOUND'::"ExerciseCategory", 'STRENGTH'::"ExerciseType", 'BACK'::"MuscleGroup", 'DUMBBELL'::"EquipmentType", NULL, ARRAY['back', 'dumbbell incline bench row', 'incline row', 'schrägbank rudern']::TEXT[], true, NOW(), NOW())
