VALUES ('ex-one-arm-dumbbell-row', 'one-arm-dumbbell-row', NULL, 'One-Arm Dumbbell Row', 'Dumbbell exercise for the back, with core, biceps assisting.', ARRAY['Choose a flat bench and place a dumbbell on each side of it.', 'Place your right hand and your right knee on the flat bench.', 'With a straight back and your stomach parallel to the weight bench, grasp the left hand side dumbbell with your left hand, palm facing towards you.', 'Pull the dumbbell straight up to the side of your chest, keeping your upper arm close to your side and keeping the torso stationary.', 'Lower the dumbbell until your arm is straight down and your elbow has only a slight bend.']::TEXT[], 'COMPOUND'::"ExerciseCategory", 'STRENGTH'::"ExerciseType", 'BACK'::"MuscleGroup", 'DUMBBELL'::"EquipmentType", NULL, ARRAY['back', 'einarmiges rudern', 'kurzhantel rudern', 'one-arm dumbbell row']::TEXT[], true, NOW(), NOW())
