VALUES ('ex-straight-arm-pulldown', 'straight-arm-pulldown', NULL, 'Straight-Arm Pulldown', 'Cable exercise for the back.', ARRAY['Start by grabbing the wide bar from the top pulley of a pulldown machine and using a wider than shoulder-width pronated grip.', 'Bend your torso slightly forward and keep your elbows slightly bent as you extend your arms straight out in front of you.', 'Pull the bar down by contracting the lats until your hands are next to the side of the thighs.', 'Reverse the motion and return to the starting position.']::TEXT[], 'CABLE'::"ExerciseCategory", 'STRENGTH'::"ExerciseType", 'BACK'::"MuscleGroup", 'CABLE'::"EquipmentType", NULL, ARRAY['back', 'pullover kabel', 'straight arm pulldown', 'überzüge kabel']::TEXT[], true, NOW(), NOW())
