VALUES ('ex-back-extension', 'back-extension', NULL, 'Back Extension', 'Machine exercise for the back, with glutes, hamstrings assisting.', ARRAY['Begin by positioning yourself in the back-extension station with legs under leg hooks.', 'With your body straight, cross your arms in front of you.', 'Lower body at waist as far down to the ground as comfortably possible.', 'Make sure to keep back naturally arched, do not bend over too far and curve back.', 'Slowly raise your torso back to the initial position as you inhale.']::TEXT[], 'ISOLATION'::"ExerciseCategory", 'STRENGTH'::"ExerciseType", 'BACK'::"MuscleGroup", 'MACHINE'::"EquipmentType", NULL, ARRAY['back', 'back extensions / hyperextensions', 'hyperextension', 'rückenstrecker']::TEXT[], true, NOW(), NOW())
