VALUES ('ex-close-grip-lat-pulldown', 'close-grip-lat-pulldown', NULL, 'Close-Grip Lat Pulldown', 'Cable exercise for the back, with biceps assisting.', ARRAY['Choose over or under hand grip.', 'Push chest forward while pulling the bar to your chin.', 'At the end of the movement, hold your arms tight to your body and accentuate the final position.', 'Slowly return to initial position and repeat.']::TEXT[], 'CABLE'::"ExerciseCategory", 'STRENGTH'::"ExerciseType", 'BACK'::"MuscleGroup", 'CABLE'::"EquipmentType", NULL, ARRAY['back', 'enger latzug', 'latzug eng', 'narrow-grip lat pulldown']::TEXT[], true, NOW(), NOW())
