VALUES ('ex-single-arm-cable-row', 'single-arm-cable-row', NULL, 'Single-Arm Seated Cable Row', 'Cable exercise for the back, with biceps assisting.', ARRAY['Sit with your knees slightly bent.', 'In initial position, your active arm and shoulder are well stretched forward, your body is turned a little to the same side.', 'Now pull your shoulder and arm all the way back while letting your body turn with the movement.']::TEXT[], 'CABLE'::"ExerciseCategory", 'STRENGTH'::"ExerciseType", 'BACK'::"MuscleGroup", 'CABLE'::"EquipmentType", NULL, ARRAY['back', 'einarmiges kabelrudern', 'seated one-arm pulley']::TEXT[], true, NOW(), NOW())
