VALUES ('ex-machine-high-row', 'machine-high-row', NULL, 'Chest-Supported Machine Row (Wide)', 'Machine exercise for the back, with shoulders assisting.', ARRAY['Sit upright slightly swaying your lower back and keeping good contact to the chest cushion.', 'Grasp handles at a wide grip, arms stretched and shoulders pushed forward.', 'Pull handles towards your chest.', 'Avoid losing contact to the chest cushion.']::TEXT[], 'MACHINE'::"ExerciseCategory", 'STRENGTH'::"ExerciseType", 'BACK'::"MuscleGroup", 'MACHINE'::"EquipmentType", NULL, ARRAY['back', 'oberer rücken', 'rudermaschine breit', 'upper back']::TEXT[], true, NOW(), NOW())
