VALUES ('ex-machine-shoulder-press', 'machine-shoulder-press', NULL, 'Machine Shoulder Press', 'Machine exercise for the shoulders, with biceps, forearms assisting.', ARRAY['Keep a tight core and flat back as you remain seated in the shoulder press machine.', 'Look straight ahead as you hold on to the handles.', 'Slowly, press the handles up above your head.', 'Do not lock out your elbow.', 'Slowly, bring the handles back down but do not let the weight stack touch.', 'Repeat the movement.']::TEXT[], 'MACHINE'::"ExerciseCategory", 'STRENGTH'::"ExerciseType", 'SHOULDERS'::"MuscleGroup", 'MACHINE'::"EquipmentType", NULL, ARRAY['machine seated shoulder press', 'schulterdrücken maschine', 'shoulders']::TEXT[], true, NOW(), NOW())
