VALUES ('ex-standing-dumbbell-shoulder-press', 'standing-dumbbell-shoulder-press', NULL, 'Standing Dumbbell Shoulder Press', 'Dumbbell exercise for the shoulders, with triceps assisting.', ARRAY['Stand upright and keep the back straight.', 'Hold a dumbbell in each hand at the shoulders with an overhand grip.', 'Thumbs should be on the inside and knuckles facing up.', 'Raise the weights above the head in a controlled motion while exhaling.', 'Pause at the top of the motion.', 'Return the dumbbells to the shoulders while inhaling.']::TEXT[], 'COMPOUND'::"ExerciseCategory", 'STRENGTH'::"ExerciseType", 'SHOULDERS'::"MuscleGroup", 'DUMBBELL'::"EquipmentType", NULL, ARRAY['schulterdrücken stehend', 'shoulders', 'standing overhead dumbbell press']::TEXT[], true, NOW(), NOW())
