VALUES ('ex-machine-lateral-raise', 'machine-lateral-raise', NULL, 'Machine Lateral Raise', 'Machine exercise for the shoulders.', ARRAY['Pick a couple of dumbbells and stand with a straight torso and the dumbbells by your side at arms length with the palms of the hand facing you. This will be your starting position.', 'While maintaining the torso in a stationary position (no swinging), lift the dumbbells to your side with a slight bend on the elbow and the hands slightly tilted forward as if pouring water in a glass. Continue to go up until you arms are parallel to the floor. Exhale as you execute this movement and pause for a second at the top.', 'Lower the dumbbells back down slowly to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::TEXT[], 'MACHINE'::"ExerciseCategory", 'STRENGTH'::"ExerciseType", 'SHOULDERS'::"MuscleGroup", 'MACHINE'::"EquipmentType", NULL, ARRAY['seitheben maschine', 'shoulders']::TEXT[], true, NOW(), NOW())
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, category = EXCLUDED.category, "primaryMuscleGroup" = EXCLUDED."primaryMuscleGroup", equipment = EXCLUDED.equipment, tags = EXCLUDED.tags, "userId" = NULL, "isSystem" = true, "updatedAt" = NOW();
VALUES ('ex-cable-lateral-raise', 'cable-lateral-raise', NULL, 'Single-Arm Cable Lateral Raise', 'Cable exercise for the shoulders.', ARRAY['Stand with your side to the machine, arm before your body, grasping the handle by a firm grip.', 'Lift your arm sideways and up.', 'Keep your elbow slightly bent during the entire movement.', 'Change arms.']::TEXT[], 'CABLE'::"ExerciseCategory", 'STRENGTH'::"ExerciseType", 'SHOULDERS'::"MuscleGroup", 'CABLE'::"EquipmentType", NULL, ARRAY['seitheben kabel', 'shoulders', 'standing one-arm side lift with cable']::TEXT[], true, NOW(), NOW())
