VALUES ('ex-barbell-front-raise', 'barbell-front-raise', NULL, 'Barbell Front Raise', 'Barbell exercise for the shoulders.', ARRAY['Grab a barbell and stand up straight.', 'Adopt a pronated, shoulder-width grip on the barbell.', 'Try to keep the torso stationary and lift the barbell to the front until your arms are slightly above the level where they would be parallel to the floor.', 'Then slowly return to the starting position.', 'Repeat as necessary.']::TEXT[], 'ISOLATION'::"ExerciseCategory", 'STRENGTH'::"ExerciseType", 'SHOULDERS'::"MuscleGroup", 'BARBELL'::"EquipmentType", NULL, ARRAY['barbell front raise', 'frontheben langhantel', 'shoulders']::TEXT[], true, NOW(), NOW())
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, category = EXCLUDED.category, "primaryMuscleGroup" = EXCLUDED."primaryMuscleGroup", equipment = EXCLUDED.equipment, tags = EXCLUDED.tags, "userId" = NULL, "isSystem" = true, "updatedAt" = NOW();
VALUES ('ex-dumbbell-front-raise', 'dumbbell-front-raise', NULL, 'Dumbbell Front Raise', 'Dumbbell exercise for the shoulders.', ARRAY['Pick up two dumbbells and stand up straight.', 'The dumbbells should be positioned in front of your thighs with your hand facing down.', 'While maintaining the torso stationary (no swinging), lift the left dumbbell to the front with a slight bend on the elbow and the palms of the hands always facing down.', 'Continue until you arm is slightly above parallel to the floor.', 'Lower the left dumbbell down slowly until you reach the starting position.', 'Lift the right dumbbell up at the same time.']::TEXT[], 'ISOLATION'::"ExerciseCategory", 'STRENGTH'::"ExerciseType", 'SHOULDERS'::"MuscleGroup", 'DUMBBELL'::"EquipmentType", NULL, ARRAY['forward / front dumbbell raise', 'frontheben', 'shoulders']::TEXT[], true, NOW(), NOW())
