VALUES ('ex-cable-upright-row', 'cable-upright-row', NULL, 'Cable Upright Row', 'Cable exercise for the shoulders, with back assisting.', ARRAY['Set the handle of the cable machine to the lowest notch.', 'Grasp the bar with both hands and palms facing down.', 'Bending at the elbows pull the bar up to the top of your chest.', 'Lower the bar back to you waist.']::TEXT[], 'CABLE'::"ExerciseCategory", 'STRENGTH'::"ExerciseType", 'SHOULDERS'::"MuscleGroup", 'CABLE'::"EquipmentType", NULL, ARRAY['aufrechtes rudern', 'cable upright row', 'shoulders']::TEXT[], true, NOW(), NOW())
