VALUES ('ex-dumbbell-reverse-fly', 'dumbbell-reverse-fly', NULL, 'Dumbbell Reverse Fly', 'Dumbbell exercise for the shoulders.', ARRAY['Lie down on an incline bench with the chest and stomach pressing against the incline.', 'Have the dumbbells in each hand with the palms facing each other.', 'Place your arms extended straight out and slightly downward, palms facing each other and elbows slightly bent.', 'Place your feet slightly wider than shoulder width apart and ground your toes for your starting position.', 'Raise the dumbbells out to the sides, squeezing your shoulder blades, until your arms are parallel to the floor and the dummbells are shoulder high.', 'Feel the contraction and slowly lower the dumbbells back down to the starting position.']::TEXT[], 'ISOLATION'::"ExerciseCategory", 'STRENGTH'::"ExerciseType", 'SHOULDERS'::"MuscleGroup", 'DUMBBELL'::"EquipmentType", NULL, ARRAY['hintere schulter', 'reverse flyes', 'reverse flys', 'shoulders', 'vorgebeugtes seitheben']::TEXT[], true, NOW(), NOW())
