VALUES ('ex-reverse-pec-deck', 'reverse-pec-deck', NULL, 'Reverse Pec Deck', 'Machine exercise for the shoulders.', ARRAY['Sit with your chest against the cushion, arms between the cushions.', 'Push your arms sidewards so that your shoulder blades are pulled together.']::TEXT[], 'MACHINE'::"ExerciseCategory", 'STRENGTH'::"ExerciseType", 'SHOULDERS'::"MuscleGroup", 'MACHINE'::"EquipmentType", NULL, ARRAY['hintere schulter maschine', 'reverse butterfly', 'reversed pec dec', 'shoulders']::TEXT[], true, NOW(), NOW())
