VALUES ('ex-cable-reverse-fly', 'cable-reverse-fly', NULL, 'Cable Reverse Fly', 'Cable exercise for the shoulders, with back assisting.', ARRAY['Stand with your arms crossed before your hips, firmly grasping the handles.', 'Lift your arms sideways and up, elbows slightly bent during the entire movement.', 'Slowly lower again and repeat.']::TEXT[], 'CABLE'::"ExerciseCategory", 'STRENGTH'::"ExerciseType", 'SHOULDERS'::"MuscleGroup", 'CABLE'::"EquipmentType", NULL, ARRAY['kabel reverse flys', 'reverse cable cross', 'shoulders', 'standing reversed cable cross']::TEXT[], true, NOW(), NOW())
