VALUES ('ex-barbell-shrug', 'barbell-shrug', NULL, 'Barbell Shrug', 'Barbell exercise for the shoulders, with back assisting.', ARRAY['Stand behind a barbell with your feet shoulder width apart.', 'Raise your shoulders up as far as you can go as you breathe out and hold the contraction for a second.', 'Pause momentarily and then breathe in as you relax your shoulders back down.']::TEXT[], 'ISOLATION'::"ExerciseCategory", 'STRENGTH'::"ExerciseType", 'SHOULDERS'::"MuscleGroup", 'BARBELL'::"EquipmentType", NULL, ARRAY['barbell shoulder shrug', 'schulterheben langhantel', 'shoulders', 'shrugs']::TEXT[], true, NOW(), NOW())
