VALUES ('ex-dumbbell-shrug', 'dumbbell-shrug', NULL, 'Dumbbell Shrug', 'Dumbbell exercise for the shoulders, with back assisting.', ARRAY['Stand up straight with a dumbbell in each hand.', 'Your palms should be facing your torso, with your arms extended to your sides.', 'Lift the dumbbells by elevating the shoulders as high as possible while you exhale.', 'Bring the dumbbells back to the starting position.']::TEXT[], 'ISOLATION'::"ExerciseCategory", 'STRENGTH'::"ExerciseType", 'SHOULDERS'::"MuscleGroup", 'DUMBBELL'::"EquipmentType", NULL, ARRAY['dumbbell shrug', 'schulterheben kurzhantel', 'shoulders']::TEXT[], true, NOW(), NOW())
