VALUES ('ex-cable-shrug', 'cable-shrug', NULL, 'Cable Shrug', 'Cable exercise for the shoulders, with back assisting.', ARRAY['Grasp a cable bar attachment that is fastened to a low pulley.', 'Your hands should be shoulder width apart, or slightly wider if you wish.', 'Stand close to the pulley with your arms extended in front of you holding the bar.', 'Lift the bar by elevating the shoulders as high as you can.', 'Lower the bar to its original position.']::TEXT[], 'CABLE'::"ExerciseCategory", 'STRENGTH'::"ExerciseType", 'SHOULDERS'::"MuscleGroup", 'CABLE'::"EquipmentType", NULL, ARRAY['cable shrug', 'schulterheben kabel', 'shoulders']::TEXT[], true, NOW(), NOW())
