VALUES ('ex-barbell-curl', 'barbell-curl', NULL, 'Barbell Curl', 'Barbell exercise for the biceps, with forearms assisting.', ARRAY['Stand up straight while holding a barbell in a shoulder-width grip.', 'The palm of your hands should be facing forward and the elbows should be close to the torso.', 'Contract your biceps to curl the weight forward.', 'Your upper arms should remain stationary during this process.', 'Continue the movement until your biceps are fully contracted and the bar is at shoulder level.', 'Hold the contracted position for a second and squeeze the biceps hard.', 'Slowly bring the barbell back to the starting position.', 'Repeat for the desired number of reps.']::TEXT[], 'ISOLATION'::"ExerciseCategory", 'STRENGTH'::"ExerciseType", 'BICEPS'::"MuscleGroup", 'BARBELL'::"EquipmentType", NULL, ARRAY['barbell curl / standing biceps curl', 'biceps', 'bizepscurls', 'langhantel curls']::TEXT[], true, NOW(), NOW())
