VALUES ('ex-seated-dumbbell-curl', 'seated-dumbbell-curl', NULL, 'Seated Dumbbell Curl', 'Dumbbell exercise for the biceps, with forearms assisting.', ARRAY['Holding a dumbbell in each hand, sit on a flat bench and extend your arms down by your sides, palms facing each other.', 'While holding the upper arm stationary, curl the weights and start twisting the wrists once the dumbbells pass your thighs so that the palms of your hands face forward at the end of the movement.', 'Slowly begin to bring the dumbbells back to the starting position as your breathe in and as you rotate the wrists back to a neutral grip.']::TEXT[], 'ISOLATION'::"ExerciseCategory", 'STRENGTH'::"ExerciseType", 'BICEPS'::"MuscleGroup", 'DUMBBELL'::"EquipmentType", NULL, ARRAY['biceps', 'kurzhantel curls sitzend', 'seated dumbbell curl']::TEXT[], true, NOW(), NOW())
