VALUES ('ex-cable-curl', 'cable-curl', NULL, 'Standing Cable Curl', 'Cable exercise for the biceps, with forearms assisting.', ARRAY['Stand up with your torso upright while holding a cable curl bar that is attached to a low pulley.', 'Grasp the bar with hands shoulder width apart and palms facing up, keeping your elbows close to your sides.', 'While holding the upper arms stationary, curl the weights while contracting the biceps as you breathe out.', 'Continue until your biceps are fully contracted.', 'Hold for a moment and then inhale as you slowly lower the bar back to the starting position.']::TEXT[], 'CABLE'::"ExerciseCategory", 'STRENGTH'::"ExerciseType", 'BICEPS'::"MuscleGroup", 'CABLE'::"EquipmentType", NULL, ARRAY['biceps', 'bizeps kabel', 'kabel curls', 'standing bicep cable curls']::TEXT[], true, NOW(), NOW())
