VALUES ('ex-ez-bar-preacher-curl', 'ez-bar-preacher-curl', NULL, 'EZ-Bar Preacher Curl', 'EZ-bar exercise for the biceps, with forearms assisting.', ARRAY['Grab an EZ-bar with an underhand grip.', 'Position hands at the first grip portion from the center.', 'With the upper arms positioned against the preacher bench pad and the chest against it, hold the E-Z Curl Bar at shoulder length.', 'Begin exercise by lowering the bar down without moving your upper arms, only allowing your forearms to move.', 'Let forearms go all the way down until it is straight with upper arm.', 'Curl weight back up to starting position.']::TEXT[], 'ISOLATION'::"ExerciseCategory", 'STRENGTH'::"ExerciseType", 'BICEPS'::"MuscleGroup", 'EZ_BAR'::"EquipmentType", NULL, ARRAY['biceps', 'ez-bar preacher curl', 'scottcurls', 'sz preacher curl']::TEXT[], true, NOW(), NOW())
