VALUES ('ex-machine-preacher-curl', 'machine-preacher-curl', NULL, 'Machine Preacher Curl', 'Machine exercise for the biceps.', ARRAY['Sit down on the Preacher Curl Machine and select the weight.', 'Position your triceps on the preacher pad and grasp the handles with an underhand grip.', 'This is the starting position.', 'Now lift the handles as you exhale and you contract the biceps.', 'At the top of the position make sure that you hold the contraction for a second.', 'Lower the handles back to the starting position.']::TEXT[], 'MACHINE'::"ExerciseCategory", 'STRENGTH'::"ExerciseType", 'BICEPS'::"MuscleGroup", 'MACHINE'::"EquipmentType", NULL, ARRAY['biceps', 'bizepsmaschine', 'machine bicep preacher / concentration curls', 'scott maschine']::TEXT[], true, NOW(), NOW())
