VALUES ('ex-overhead-cable-curl', 'overhead-cable-curl', NULL, 'Overhead Cable Curl', 'Cable exercise for the biceps.', ARRAY['Stand in the middle of two high pulleys and grasp a handle with each hand.', 'Your upper arms should be positioned so that they are parallel to the floor with the palms of your hands facing you.', 'This is the starting position for the exercise.', 'Slowly squeeze the biceps on each side until your forearms and biceps touch exhaling while you do so.', 'Slowly bring your arms back to the starting position.']::TEXT[], 'CABLE'::"ExerciseCategory", 'STRENGTH'::"ExerciseType", 'BICEPS'::"MuscleGroup", 'CABLE'::"EquipmentType", NULL, ARRAY['biceps', 'crucifix curl', 'kabel curls über kopf', 'overhead cable curl / crucifix curl']::TEXT[], true, NOW(), NOW())
