VALUES ('ex-close-grip-bench-press', 'close-grip-bench-press', NULL, 'Close-Grip Bench Press', 'Barbell exercise for the triceps, with chest, shoulders assisting.', ARRAY['Lie back on a flat bench.', 'Using a close grip (around shoulder width) lift the bar off the rack and hold it straight over you, keeping your arms locked.', 'Lower the bar to the sternum by flexing the elbows.', 'Maintain control and do not bounce the bar off of your chest.', 'After touching your torso with the bar, extend the elbows to return the bar to the starting position.']::TEXT[], 'COMPOUND'::"ExerciseCategory", 'STRENGTH'::"ExerciseType", 'TRICEPS'::"MuscleGroup", 'BARBELL'::"EquipmentType", NULL, ARRAY['close-grip overhand barbell bench press', 'enges bankdrücken', 'triceps']::TEXT[], true, NOW(), NOW())
