VALUES ('ex-dumbbell-skull-crusher', 'dumbbell-skull-crusher', NULL, 'Lying Dumbbell Triceps Extension', 'Dumbbell exercise for the triceps, with shoulders assisting.', ARRAY['Lie down on a flat bench holding two dumbbells directly above your shoulders.', 'Your arms should be fully extended and form a 90 degree angle from your torso and the floor.', 'Your palms should be facing in and your elbows should be tucked in close to your body.', 'This is your starting position.', 'Lower the dumbbells slowly until they are positioned near your ears.', 'Inhale as you do so, keeping your upper arms stationary.', 'Use your triceps to bring the weight up to the starting position.', 'Exhale as you perform this part of the exercise.']::TEXT[], 'ISOLATION'::"ExerciseCategory", 'STRENGTH'::"ExerciseType", 'TRICEPS'::"MuscleGroup", 'DUMBBELL'::"EquipmentType", NULL, ARRAY['french press kurzhantel', 'lying dumbbell tricep extension', 'stirndrücken', 'triceps']::TEXT[], true, NOW(), NOW())
