VALUES ('ex-single-arm-overhead-dumbbell-extension', 'single-arm-overhead-dumbbell-extension', NULL, 'Single-Arm Overhead Dumbbell Extension', 'Dumbbell exercise for the triceps.', ARRAY['Sit down on a bench with your back upright, feet planted on the ground and a dumbbell in one hand.', 'Raise the dumbbell up until you armi is fully extended.', 'Lower the dumbbell to the back of your head.']::TEXT[], 'ISOLATION'::"ExerciseCategory", 'STRENGTH'::"ExerciseType", 'TRICEPS'::"MuscleGroup", 'DUMBBELL'::"EquipmentType", NULL, ARRAY['einarmiges trizepsdrücken', 'seated single arm overhead dumbbell tricep extensions', 'triceps']::TEXT[], true, NOW(), NOW())
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, category = EXCLUDED.category, "primaryMuscleGroup" = EXCLUDED."primaryMuscleGroup", equipment = EXCLUDED.equipment, tags = EXCLUDED.tags, "userId" = NULL, "isSystem" = true, "updatedAt" = NOW();
VALUES ('ex-dumbbell-kickback', 'dumbbell-kickback', NULL, 'Dumbbell Triceps Kickback', 'Dumbbell exercise for the triceps, with forearms assisting.', ARRAY['Brace one knee and one hand on a flat bench while keeping the other leg flat on the floor.', 'Your back should be flat and your torso should be parallel with the bench.', 'Hold a dumbbell in the free hand with your palm facing inward.', 'Your arm should be bent at a 90 degree angle so that the dumbbell is next to your waist and your upper arm is parallel with the floor.', 'This is your starting position.', 'Without moving your upper arm, exhale and extend your arm completely back so that your entire arm is parallel with the floor and the dumbbell is perpendicular to the floor.', 'Hold for a moment and then slowly reverse the motion back to the starting position.']::TEXT[], 'ISOLATION'::"ExerciseCategory", 'STRENGTH'::"ExerciseType", 'TRICEPS'::"MuscleGroup", 'DUMBBELL'::"EquipmentType", NULL, ARRAY['kickbacks', 'tricep dumbbell kickback', 'triceps']::TEXT[], true, NOW(), NOW())
