VALUES ('ex-triceps-dip', 'triceps-dip', NULL, 'Triceps Dip', 'Bodyweight exercise for the triceps, with chest, forearms assisting.', ARRAY['Place your hands on the dip bars and face your body out.', 'Bend at the elbows and lower your body down till your arms make a 90 degree angle.', 'Push yourself back up and then bring your knees up to your waist.', 'Lower them back down.', 'This completes one repetition.']::TEXT[], 'BODYWEIGHT'::"ExerciseCategory", 'STRENGTH'::"ExerciseType", 'TRICEPS'::"MuscleGroup", 'BODYWEIGHT'::"EquipmentType", NULL, ARRAY['barrenstütz', 'dips', 'triceps', 'triceps dips']::TEXT[], true, NOW(), NOW())
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, category = EXCLUDED.category, "primaryMuscleGroup" = EXCLUDED."primaryMuscleGroup", equipment = EXCLUDED.equipment, tags = EXCLUDED.tags, "userId" = NULL, "isSystem" = true, "updatedAt" = NOW();
VALUES ('ex-bench-dip', 'bench-dip', NULL, 'Bench Dip', 'Bodyweight exercise for the triceps, with chest, shoulders assisting.', ARRAY['Balance yourself between two flat benches so that your arms are behind your back on one bench and your ankles are crossed in front of you on the other one.', 'For the starting position, your arms should be fully extended so that your legs are parallel with the floor.', 'The top half of your body should form a 90 degree angle with your legs.', 'Have a partner place a weight plate on your lap.', 'Slowly lower your body as you inhale by bending at the elbows until you lower yourself far enough to where there is an angle slightly smaller than 90 degrees between the upper arm and the forearm.', 'Exhale as you raise your body back up to the starting position.']::TEXT[], 'BODYWEIGHT'::"ExerciseCategory", 'STRENGTH'::"ExerciseType", 'TRICEPS'::"MuscleGroup", 'BODYWEIGHT'::"EquipmentType", NULL, ARRAY['bankdips', 'triceps', 'weighted bench dip']::TEXT[], true, NOW(), NOW())
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, category = EXCLUDED.category, "primaryMuscleGroup" = EXCLUDED."primaryMuscleGroup", equipment = EXCLUDED.equipment, tags = EXCLUDED.tags, "userId" = NULL, "isSystem" = true, "updatedAt" = NOW();
VALUES ('ex-reverse-grip-cable-pushdown', 'reverse-grip-cable-pushdown', NULL, 'Single-Arm Reverse-Grip Pushdown', 'Cable exercise for the triceps.', ARRAY['Firmly grasp the handle, palm of your hand turning upward.', 'Keep your elbow tight to your body and push down till your elbow is fully stretched.', 'Slowly return to initial position and repeat.']::TEXT[], 'CABLE'::"ExerciseCategory", 'STRENGTH'::"ExerciseType", 'TRICEPS'::"MuscleGroup", 'CABLE'::"EquipmentType", NULL, ARRAY['supinated one-arm triceps press', 'triceps', 'trizepsdrücken untergriff']::TEXT[], true, NOW(), NOW())
