VALUES ('ex-bodyweight-squat', 'bodyweight-squat', NULL, 'Bodyweight Squat', 'Bodyweight exercise for the quads, with core, calves assisting.', ARRAY['Stand with your feet hip width apart.', 'Your toes should be pointing straight ahead or only slightly outward.', 'Cross your arms in front of your body, place your hands behind your head (prisoner squat) or at the sides of your head.', 'Keep your weight on your heels and bend your knees while lowering your hips towards the ground as if you are sitting down on a chair.', 'Keep your back straight at all times.', 'Continue until you feel a slight stretch in your quadriceps.', 'Pause for a count of one.', 'Do not let your knees extend out beyond the level of your toes.']::TEXT[], 'BODYWEIGHT'::"ExerciseCategory", 'STRENGTH'::"ExerciseType", 'QUADRICEPS'::"MuscleGroup", 'BODYWEIGHT'::"EquipmentType", NULL, ARRAY['air squat', 'bodyweight squat', 'kniebeuge ohne gewicht', 'quads']::TEXT[], true, NOW(), NOW())
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, category = EXCLUDED.category, "primaryMuscleGroup" = EXCLUDED."primaryMuscleGroup", equipment = EXCLUDED.equipment, tags = EXCLUDED.tags, "userId" = NULL, "isSystem" = true, "updatedAt" = NOW();
VALUES ('ex-dumbbell-lunge', 'dumbbell-lunge', NULL, 'Dumbbell Lunge', 'Dumbbell exercise for the quads, with core, calves assisting.', ARRAY['Grab a dumbbell in each hand and hold them at side of body with arms straight.', 'Step forward with your right leg around 2 feet or so from the foot being left stationary behind and lower your upper body down.', 'Step back to return to starting position.']::TEXT[], 'COMPOUND'::"ExerciseCategory", 'STRENGTH'::"ExerciseType", 'QUADRICEPS'::"MuscleGroup", 'DUMBBELL'::"EquipmentType", NULL, ARRAY['ausfallschritte kurzhantel', 'dumbbell lunges', 'quads']::TEXT[], true, NOW(), NOW())
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, category = EXCLUDED.category, "primaryMuscleGroup" = EXCLUDED."primaryMuscleGroup", equipment = EXCLUDED.equipment, tags = EXCLUDED.tags, "userId" = NULL, "isSystem" = true, "updatedAt" = NOW();
VALUES ('ex-barbell-lunge', 'barbell-lunge', NULL, 'Barbell Lunge', 'Barbell exercise for the quads, with core, calves assisting.', ARRAY['Stand in an upright position with feet shoulder width apart and a barbell across the top of your shoulders and your hands on each side of the bar with palms facing forward.', 'Step forward with your right leg and squat down through your hips, while keeping the torso upright and maintaining balance.', 'Take a step backwards to return to starting position and then repeat the movement with the opposite leg.']::TEXT[], 'COMPOUND'::"ExerciseCategory", 'STRENGTH'::"ExerciseType", 'QUADRICEPS'::"MuscleGroup", 'BARBELL'::"EquipmentType", NULL, ARRAY['ausfallschritte langhantel', 'barbell lunge', 'quads']::TEXT[], true, NOW(), NOW())
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, category = EXCLUDED.category, "primaryMuscleGroup" = EXCLUDED."primaryMuscleGroup", equipment = EXCLUDED.equipment, tags = EXCLUDED.tags, "userId" = NULL, "isSystem" = true, "updatedAt" = NOW();
VALUES ('ex-goblet-squat', 'goblet-squat', NULL, 'Goblet Squat', 'Dumbbell exercise for the quads, with core, calves assisting.', ARRAY['Stand up straight and hold a light dumbbell close to your chest.', 'This is the starting position.', 'Squat down until your hamstrings are on your calves.', 'Once you get to the bottom of the squat, pause and use your elbows to push your knees out.', 'Return to the starting position.']::TEXT[], 'COMPOUND'::"ExerciseCategory", 'STRENGTH'::"ExerciseType", 'QUADRICEPS'::"MuscleGroup", 'DUMBBELL'::"EquipmentType", NULL, ARRAY['goblet kniebeuge', 'goblet squat', 'quads']::TEXT[], true, NOW(), NOW())
