VALUES ('ex-smith-machine-squat', 'smith-machine-squat', NULL, 'Smith Machine Squat', 'Smith machine exercise for the quads, with calves assisting.', ARRAY['Stand with your feet turned slightly outwards, bar resting on your shoulders.', 'Bend your knees to about 90 degrees and push back upwards.', 'Keep your back straight and look straight ahead during the entire exercise.']::TEXT[], 'MACHINE'::"ExerciseCategory", 'STRENGTH'::"ExerciseType", 'QUADRICEPS'::"MuscleGroup", 'SMITH_MACHINE'::"EquipmentType", NULL, ARRAY['kniebeuge multipresse', 'quads', 'smith rack squat']::TEXT[], true, NOW(), NOW())
