VALUES ('ex-glute-bridge', 'glute-bridge', NULL, 'Glute Bridge', 'Bodyweight exercise for the glutes, with core, back assisting.', ARRAY['Lie flat on the floor on your back with the hands by your side and your knees bent.', 'Your feet should be placed around shoulder width.', 'Begin exercise by squeezing your glutes and raising hips up until your body forms a straight line from your knees to your shoulders.', 'Hold for at least 5 seconds, then lower back down.']::TEXT[], 'BODYWEIGHT'::"ExerciseCategory", 'STRENGTH'::"ExerciseType", 'GLUTES'::"MuscleGroup", 'BODYWEIGHT'::"EquipmentType", NULL, ARRAY['beckenheben', 'glutes', 'hip raise', 'hip raise / butt lift / bridge']::TEXT[], true, NOW(), NOW())
