VALUES ('ex-weighted-glute-bridge', 'weighted-glute-bridge', NULL, 'Weighted Glute Bridge', 'Barbell exercise for the glutes, with core, hamstrings assisting.', ARRAY['Lie down with back on an exercise mat and arms straight at your sides.', 'Place a weight plate on your hips and hold in place with your hands.', 'Begin the movement by driving through with your heels, extending your hips vertically through the bar.', 'Extend as far as possible, then reverse the motion to return to the starting position.']::TEXT[], 'COMPOUND'::"ExerciseCategory", 'STRENGTH'::"ExerciseType", 'GLUTES'::"MuscleGroup", 'BARBELL'::"EquipmentType", NULL, ARRAY['beckenheben mit gewicht', 'glutes', 'weighted glute bridge']::TEXT[], true, NOW(), NOW())
