VALUES ('ex-standing-leg-curl', 'standing-leg-curl', NULL, 'Standing Leg Curl', 'Machine exercise for the hamstrings, with glutes assisting.', ARRAY['Place yourself on a leg curl machine so that your knees are against the knee pads and your chest is against the chest pad.Place the back of your right leg underneath the curl pad so your calf is pressing against it and your toes are extended straight.', 'Curl your right leg up as far as possible without lifting the upper leg from the pad.', 'Hold for a moment and then bring the legs back to the initial position.']::TEXT[], 'MACHINE'::"ExerciseCategory", 'STRENGTH'::"ExerciseType", 'HAMSTRINGS'::"MuscleGroup", 'MACHINE'::"EquipmentType", NULL, ARRAY['beinbeuger stehend', 'hamstrings', 'standing leg / hamstring curl']::TEXT[], true, NOW(), NOW())
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, category = EXCLUDED.category, "primaryMuscleGroup" = EXCLUDED."primaryMuscleGroup", equipment = EXCLUDED.equipment, tags = EXCLUDED.tags, "userId" = NULL, "isSystem" = true, "updatedAt" = NOW();
VALUES ('ex-crunch', 'crunch', NULL, 'Crunch', 'Bodyweight exercise for the core.', ARRAY['Lie down on the floor on your back and bend your knees, placing your hands behind your head or across your chest.', 'Brace your core.', 'Crunch your ribs toward your pelvis using your abdominal muscles to initiate and complete the movement.', 'Exhale as you come up and keep your neck straight, chin up.', 'Hold at the top of the movement for a few seconds, breathing continuously.', 'Lower slowly back down.']::TEXT[], 'BODYWEIGHT'::"ExerciseCategory", 'STRENGTH'::"ExerciseType", 'ABS_CORE'::"MuscleGroup", 'BODYWEIGHT'::"EquipmentType", NULL, ARRAY['bauchpresse', 'core', 'crunches']::TEXT[], true, NOW(), NOW())
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, category = EXCLUDED.category, "primaryMuscleGroup" = EXCLUDED."primaryMuscleGroup", equipment = EXCLUDED.equipment, tags = EXCLUDED.tags, "userId" = NULL, "isSystem" = true, "updatedAt" = NOW();
VALUES ('ex-decline-crunch', 'decline-crunch', NULL, 'Decline Bench Crunch', 'Bodyweight exercise for the core.', ARRAY['Secure your legs at the end of the decline bench and lie down.', 'Place hands behind head or cross arms over chest.', 'Begin exercise by raising torso to a sitting position, pause, then lower back down.']::TEXT[], 'BODYWEIGHT'::"ExerciseCategory", 'STRENGTH'::"ExerciseType", 'ABS_CORE'::"MuscleGroup", 'BODYWEIGHT'::"EquipmentType", NULL, ARRAY['core', 'decline bench crunches / sit-ups', 'negativbank crunch', 'sit-up']::TEXT[], true, NOW(), NOW())
