VALUES ('ex-machine-crunch', 'machine-crunch', NULL, 'Ab Crunch Machine', 'Machine exercise for the core.', ARRAY['Select an appropriate resistance and sit down on the ab machine placing your feet under the pads provided and grabbing the top handles.', 'Your arms should be bent at a 90 degree angle as you rest the triceps on the pads provided.', 'This will be your starting position.', 'Next, tighten the abdominals and while breathing out, crunch your abs.', 'To do this, bend at the waist, lowering the hand bars and lifting the legs.', 'Breathing in, straighten your torso without letting the weight plates hit.', 'Pause briefly and then repeat.']::TEXT[], 'MACHINE'::"ExerciseCategory", 'STRENGTH'::"ExerciseType", 'ABS_CORE'::"MuscleGroup", 'MACHINE'::"EquipmentType", NULL, ARRAY['ab crunch machine', 'bauchmaschine', 'core']::TEXT[], true, NOW(), NOW())
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, instructions = EXCLUDED.instructions, category = EXCLUDED.category, "primaryMuscleGroup" = EXCLUDED."primaryMuscleGroup", equipment = EXCLUDED.equipment, tags = EXCLUDED.tags, "userId" = NULL, "isSystem" = true, "updatedAt" = NOW();
VALUES ('ex-alternate-heel-touchers', 'alternate-heel-touchers', NULL, 'Alternate Heel Touchers', 'Bodyweight exercise for the core.', ARRAY['Lie on the floor or an exercise mat with the knees bent and the feet on the floor around 18-24 inches apart.', 'Breathing out, crunch your ab slightly upward and sideways to the right a couple of inches until your right hand touches your right heel.', 'Now go back slowly to the starting position as you inhale.', 'Repeat on the other side.']::TEXT[], 'BODYWEIGHT'::"ExerciseCategory", 'STRENGTH'::"ExerciseType", 'ABS_CORE'::"MuscleGroup", 'BODYWEIGHT'::"EquipmentType", NULL, ARRAY['alternate heel touchers', 'core', 'fersen tippen', 'seitliche bauchmuskeln']::TEXT[], true, NOW(), NOW())
