VALUES ('ex-flutter-kicks', 'flutter-kicks', NULL, 'Flutter Kicks', 'Bodyweight exercise for the core, with glutes assisting.', ARRAY['Lie facedown on a flat bench with the hips on the edge of the bench and the legs straight.', 'Start the movement by lifting the left leg higher than the right leg.', 'Then lower the left leg as you lift the right leg.', 'Continue alternating.']::TEXT[], 'BODYWEIGHT'::"ExerciseCategory", 'STRENGTH'::"ExerciseType", 'ABS_CORE'::"MuscleGroup", 'BODYWEIGHT'::"EquipmentType", NULL, ARRAY['beinschlag', 'bench flutter kicks', 'core']::TEXT[], true, NOW(), NOW())
