VALUES ('ex-elbow-to-knee-crunch', 'elbow-to-knee-crunch', NULL, 'Elbow-to-Knee Crunch', 'Bodyweight exercise for the core, with glutes, quads assisting.', ARRAY['Crunch your left knee, while bending it, and right elbow so that they meet at the center of your body.', 'Return to starting position and crunch your right knee to your left elbow.']::TEXT[], 'BODYWEIGHT'::"ExerciseCategory", 'STRENGTH'::"ExerciseType", 'ABS_CORE'::"MuscleGroup", 'BODYWEIGHT'::"EquipmentType", NULL, ARRAY['core', 'elbow-to-knee crunches', 'ellbogen zum knie']::TEXT[], true, NOW(), NOW())
