VALUES ('ex-bird-dog', 'bird-dog', NULL, 'Bird Dog', 'Bodyweight exercise for the core, with glutes assisting.', ARRAY['Get down on your hands and knees with your arms shoulder-width apart and hands directly underneath your shoulders.', 'Begin the exercise by simultaneously raising your right arm up and your left leg up at the same time until they are both in line with the rest of your body.', 'Hold this position for a brief moment and then return to starting position.', 'Repeat with opposite leg and arm.']::TEXT[], 'BODYWEIGHT'::"ExerciseCategory", 'STRENGTH'::"ExerciseType", 'ABS_CORE'::"MuscleGroup", 'BODYWEIGHT'::"EquipmentType", NULL, ARRAY['alternating reach & kickback', 'alternating reach kickback', 'core', 'vierfüßlerstand']::TEXT[], true, NOW(), NOW())
