VALUES ('ex-cable-core-rotation', 'cable-core-rotation', NULL, 'Cable Core Rotation', 'Cable exercise for the core.', ARRAY['Hold a cable with both hands to your right side, so your left arm is straight and stretched across your body.', 'Pull the cable to the opposite side rotating your torso until your right arm is straight.', 'Return the cable back to starting position and repeat.']::TEXT[], 'CABLE'::"ExerciseCategory", 'STRENGTH'::"ExerciseType", 'ABS_CORE'::"MuscleGroup", 'CABLE'::"EquipmentType", NULL, ARRAY['cable core rotation', 'core', 'rumpfrotation kabel', 'woodchopper']::TEXT[], true, NOW(), NOW())
