VALUES ('ex-captains-chair-knee-raise', 'captains-chair-knee-raise', NULL, 'Captain''s Chair Knee Raise', 'Machine exercise for the core, with back assisting.', ARRAY['Place your forearms are on the pads or bars of the apparatus you are using and grip the handles or bars.', 'Your arms should be bent at 90 degrees and your upper arms in a straight line with your sides.', 'Your torso should be straight and your lower back pressed against the pad of the bench if using one.', 'Keep your legs extended and pointing down to the floor.', 'This is the start position.', 'Exhale and as you do so, lift your legs up in a smooth arc bending at the knees until your thighs are about parallel to the floor.', 'Hold for a count of one.', 'Return to the start position in a smooth, controlled movement while inhaling.']::TEXT[], 'BODYWEIGHT'::"ExerciseCategory", 'STRENGTH'::"ExerciseType", 'ABS_CORE'::"MuscleGroup", 'MACHINE'::"EquipmentType", NULL, ARRAY['beinheben stütz', 'captain''s chair leg / knee / hip raise', 'core', 'knieheben']::TEXT[], true, NOW(), NOW())
