VALUES ('ex-side-plank', 'side-plank', NULL, 'Side Plank', 'Bodyweight exercise for the core.', ARRAY['Lie on your right side, legs extended and stacked from hip to feet.', 'The elbow of your right arm is directly under your shoulder.', 'Ensure your head is directly in line with your spine.', 'Your left arm can be aligned along the left side of your body.', 'Engage your abdominal muscles, drawing your navel toward your spine.', 'Lift your hips and knees from the mat while exhaling.', 'Your torso is straight in line with no sagging or bending.', 'Hold the position.']::TEXT[], 'BODYWEIGHT'::"ExerciseCategory", 'STRENGTH'::"ExerciseType", 'ABS_CORE'::"MuscleGroup", 'BODYWEIGHT'::"EquipmentType", NULL, ARRAY['core', 'seitstütz', 'side plank']::TEXT[], true, NOW(), NOW())
