VALUES ('ex-side-jackknife', 'side-jackknife', NULL, 'Side Jackknife', 'Bodyweight exercise for the core, with glutes assisting.', ARRAY['Lie on your left side, your legs stacked and straight.', 'Wrap your left arm in front of your torso, placing it on your right hip, and put your right hand behind your head.', 'Simultaneously raise your torso and legs, bringing your head toward your hips.', 'Return to start in a controlled motion.']::TEXT[], 'BODYWEIGHT'::"ExerciseCategory", 'STRENGTH'::"ExerciseType", 'ABS_CORE'::"MuscleGroup", 'BODYWEIGHT'::"EquipmentType", NULL, ARRAY['core', 'double side jackknife', 'seitliches klappmesser']::TEXT[], true, NOW(), NOW())
