VALUES ('ex-jackknife-sit-up', 'jackknife-sit-up', NULL, 'Jackknife Sit-Up', 'Bodyweight exercise for the core, with glutes assisting.', ARRAY['Lie on your back on an exercise mat on the floor with your legs touching and fully extended and your arms extended outward with palms down.', 'As you exhale, bend at the waist while simultaneously raising your legs and arms to meet in a jackknife position.', 'While inhaling, lower your arms and legs back to the starting position.']::TEXT[], 'BODYWEIGHT'::"ExerciseCategory", 'STRENGTH'::"ExerciseType", 'ABS_CORE'::"MuscleGroup", 'BODYWEIGHT'::"EquipmentType", NULL, ARRAY['core', 'jackknife sit-up / crunch / toe touches', 'klappmesser', 'v-up']::TEXT[], true, NOW(), NOW())
