VALUES ('ex-leg-pull-in', 'leg-pull-in', NULL, 'Leg Pull-In', 'Bodyweight exercise for the core, with back assisting.', ARRAY['Lie on an exercise mat with your legs extended and your hands either palms facing down next to you or under your glutes.', 'Bend your knees and raise your legs so that they form a 90 degree angle.', 'Begin exercise by extending your legs out and touching the floor with your toes so that you feel a tight stretch in your lower abs.', 'Return to the starting position.']::TEXT[], 'BODYWEIGHT'::"ExerciseCategory", 'STRENGTH'::"ExerciseType", 'ABS_CORE'::"MuscleGroup", 'BODYWEIGHT'::"EquipmentType", NULL, ARRAY['core', 'knieheben liegend', 'leg pull-in knee-up']::TEXT[], true, NOW(), NOW())
