VALUES ('ex-lying-leg-raise', 'lying-leg-raise', NULL, 'Lying Leg Raise', 'Bodyweight exercise for the core, with back assisting.', ARRAY['Lay down with your back flat on the floor, feet straight out and together and your hands on your side.', 'While keep your legs as straight as you can lift your feet up in the air between 6-12 inches.', 'You can either hold for designated period of time or you can raise them up and then lower them right back down.']::TEXT[], 'BODYWEIGHT'::"ExerciseCategory", 'STRENGTH'::"ExerciseType", 'ABS_CORE'::"MuscleGroup", 'BODYWEIGHT'::"EquipmentType", NULL, ARRAY['beinheben liegend', 'core', 'lying leg raise / lift']::TEXT[], true, NOW(), NOW())
