VALUES ('ex-reverse-crunch', 'reverse-crunch', NULL, 'Reverse Crunch', 'Bodyweight exercise for the core, with glutes assisting.', ARRAY['Lie face up on a falt bench.', 'Place hands behind head and raise head off the ground.', 'Next, lift your legs and bend knees so that they form a 90-degree angle.', 'Hips are still on the ground at this time.', 'Begin exercise by raising your hips off the ground and toward your head.', 'Pause for a moment, then lower back down and repeat.']::TEXT[], 'BODYWEIGHT'::"ExerciseCategory", 'STRENGTH'::"ExerciseType", 'ABS_CORE'::"MuscleGroup", 'BODYWEIGHT'::"EquipmentType", NULL, ARRAY['core', 'reverse bench crunch', 'umgekehrter crunch']::TEXT[], true, NOW(), NOW())
