VALUES ('ex-exercise-ball-crunch', 'exercise-ball-crunch', NULL, 'Exercise Ball Crunch', 'Equipment-based exercise for the core.', ARRAY['Lie on an exercise ball with your lower back pressed against the surface of the ball.', 'Your legs should be bent at the knee, your feet should be flat on the floor.', 'When you are in the proper position, your upper torso should be hanging off the top of the ball.', 'Keep your arms at your sides or crossed on top of your chest.', 'Lower your torso into a stretch position keeping the neck stationary at all times.', 'This will be your starting position.', 'With your hips stationary, contract your abs to flex your waist.', 'Curl your shoulders and trunk up until you feel a contraction in your abs.']::TEXT[], 'BODYWEIGHT'::"ExerciseCategory", 'STRENGTH'::"ExerciseType", 'ABS_CORE'::"MuscleGroup", 'OTHER'::"EquipmentType", NULL, ARRAY['core', 'gymnastikball crunch', 'swiss ball', 'swiss ball crunch']::TEXT[], true, NOW(), NOW())
