DROP TABLE IF EXISTS _legacy_exercise_slug_map;
CREATE TEMP TABLE _legacy_exercise_slug_map (old_slug TEXT PRIMARY KEY, new_slug TEXT NOT NULL);

DROP TABLE IF EXISTS _legacy_exercise_id_map;
CREATE TEMP TABLE _legacy_exercise_id_map AS
  SELECT o.id AS old_id, n.id AS new_id
  FROM _legacy_exercise_slug_map m
  JOIN "Exercise" o ON o.slug = m.old_slug
  JOIN "Exercise" n ON n.slug = m.new_slug
  WHERE o.id <> n.id;

UPDATE "WorkoutTemplateExercise" t SET "exerciseId" = m.new_id FROM _legacy_exercise_id_map m WHERE t."exerciseId" = m.old_id;
UPDATE "StretchingRoutineExercise" t SET "exerciseId" = m.new_id FROM _legacy_exercise_id_map m WHERE t."exerciseId" = m.old_id;
UPDATE "SessionExercise" t SET "exerciseId" = m.new_id FROM _legacy_exercise_id_map m WHERE t."exerciseId" = m.old_id;

UPDATE "WorkoutTemplateExercise" t
SET "alternativeExerciseIds" = (
  SELECT COALESCE(array_agg(DISTINCT COALESCE(m.new_id, u.alt_id)), ARRAY[]::TEXT[])
  FROM unnest(t."alternativeExerciseIds") AS u(alt_id)
  LEFT JOIN _legacy_exercise_id_map m ON m.old_id = u.alt_id
)
WHERE t."alternativeExerciseIds" && (SELECT COALESCE(array_agg(old_id), ARRAY[]::TEXT[]) FROM _legacy_exercise_id_map);

UPDATE "SessionExercise" t
SET "alternativeExerciseIds" = (
  SELECT COALESCE(array_agg(DISTINCT COALESCE(m.new_id, u.alt_id)), ARRAY[]::TEXT[])
  FROM unnest(t."alternativeExerciseIds") AS u(alt_id)
  LEFT JOIN _legacy_exercise_id_map m ON m.old_id = u.alt_id
)
WHERE t."alternativeExerciseIds" && (SELECT COALESCE(array_agg(old_id), ARRAY[]::TEXT[]) FROM _legacy_exercise_id_map);

DELETE FROM "ExerciseAlternative"
WHERE "exerciseId" IN (SELECT old_id FROM _legacy_exercise_id_map)
   OR "alternativeExerciseId" IN (SELECT old_id FROM _legacy_exercise_id_map);

DELETE FROM "Exercise" WHERE id IN (SELECT old_id FROM _legacy_exercise_id_map);

DROP TABLE _legacy_exercise_id_map;
DROP TABLE _legacy_exercise_slug_map;
